import { describe, expect, it } from "vitest";
import { curl } from "../../src/export/curl.ts";
import { getItems, postBig, postForm, postItem, postUpload } from "../fixtures-export.ts";
import { OPTIONS, leaked, redacted, sourceOf } from "./helpers.ts";

const render = (f: Parameters<typeof redacted>[0]) => curl(redacted(f).source, OPTIONS);

describe("cURL (007, contracts/exporters.md, FR-012)", () => {
  it("GET: sin -X, una opción por línea y valores sensibles redactados", () => {
    expect(render(getItems)).toBe(
      [
        "# Generated by Nahual 1.0.0",
        "curl 'http://127.0.0.1:4311/export/items?page=1' \\",
        "  -H 'accept: application/json' \\",
        "  -H 'authorization: <redacted>' \\",
        "  -H 'user-agent: Mozilla/5.0'",
        "",
      ].join("\n"),
    );
  });

  it("POST JSON: -X, --data-raw y comillas simples escapadas", () => {
    const code = render(postItem);
    expect(code).toContain("  -X POST \\\n");
    expect(code).toContain("token=<redacted>&lang=es'");
    expect(code).toContain(
      `--data-raw '{"name":"it'\\''s \\"x\\" $HOME","password":"<redacted>"}'`,
    );
    expect(leaked(code)).toEqual([]);
  });

  it("formulario con --data-urlencode y multipart con --form-string sin content-type propio", () => {
    expect(render(postForm)).toContain(
      "--data-urlencode 'a=1' \\\n  --data-urlencode 'session_id=<redacted>'",
    );
    const upload = render(postUpload);
    expect(upload).toContain("--form-string 'note=hola'");
    expect(upload).toContain("# omitted file part: file (photo.png)");
    expect(upload).not.toContain("content-type: multipart");
  });

  it("body omitido: comentario con el motivo y el comando sigue siendo ejecutable", () => {
    const code = render(postBig);
    expect(code).toMatch(/^# body omitted: tooLarge \(1\.5 MB\)$/m);
    expect(code).not.toContain("--data");
    expect(code.trimEnd().endsWith("\\")).toBe(false);
  });

  it("con includeSensitive (fuente sin redactar) incluye los valores", () => {
    expect(curl(sourceOf(getItems), OPTIONS)).toContain(
      "authorization: Bearer secret-export-token",
    );
  });

  it("es determinista", () => {
    expect(render(postItem)).toBe(render(postItem));
  });
});
